import fs from "node:fs";
import path from "node:path";
import { parseGuide, type Guide } from "./schema";

/**
 * Two tiers:
 *  1. Curated library: JSON files in /data/guides, validated on load, human-reviewed.
 *  2. Live cache: guides generated by the agent at runtime. Upstash Redis if configured,
 *     otherwise an in-memory Map (fine for local dev; resets on serverless cold start).
 */

const GUIDES_DIR = path.join(process.cwd(), "data", "guides");

let libraryCache: Guide[] | null = null;

export function loadLibrary(): Guide[] {
  if (libraryCache && process.env.NODE_ENV === "production") return libraryCache;
  if (!fs.existsSync(GUIDES_DIR)) return [];
  const guides: Guide[] = [];
  for (const file of fs.readdirSync(GUIDES_DIR).filter((f) => f.endsWith(".json")).sort()) {
    const raw = JSON.parse(fs.readFileSync(path.join(GUIDES_DIR, file), "utf8"));
    try {
      guides.push(parseGuide(raw));
    } catch (e) {
      console.error(`Skipping invalid curated guide ${file}:`, (e as Error).message);
    }
  }
  libraryCache = guides;
  return guides;
}

// ---- live cache -----------------------------------------------------------

type Cache = {
  get(slug: string): Promise<Guide | null>;
  set(slug: string, guide: Guide): Promise<void>;
  list(): Promise<Guide[]>;
};

const memory = new Map<string, Guide>();
const memoryCache: Cache = {
  async get(slug) {
    return memory.get(slug) ?? null;
  },
  async set(slug, guide) {
    memory.set(slug, guide);
  },
  async list() {
    return [...memory.values()].sort((a, b) => b.generatedAt.localeCompare(a.generatedAt));
  }
};

let redisCache: Cache | null = null;
async function getRedisCache(): Promise<Cache | null> {
  if (redisCache) return redisCache;
  const url = process.env.UPSTASH_REDIS_REST_URL;
  const token = process.env.UPSTASH_REDIS_REST_TOKEN;
  if (!url || !token) return null;
  const { Redis } = await import("@upstash/redis");
  const redis = new Redis({ url, token });
  const KEY = (slug: string) => `guide:${slug}`;
  const INDEX = "guide:index";
  redisCache = {
    async get(slug) {
      const raw = await redis.get<Guide>(KEY(slug));
      return raw ? parseGuide(raw) : null;
    },
    async set(slug, guide) {
      await redis.set(KEY(slug), guide);
      await redis.zadd(INDEX, { score: Date.parse(guide.generatedAt), member: slug });
    },
    async list() {
      const slugs = await redis.zrange<string[]>(INDEX, 0, 49, { rev: true });
      const out: Guide[] = [];
      for (const s of slugs) {
        const g = await redis.get<Guide>(KEY(s));
        if (g) out.push(parseGuide(g));
      }
      return out;
    }
  };
  return redisCache;
}

async function cache(): Promise<Cache> {
  return (await getRedisCache()) ?? memoryCache;
}

/**
 * Look up a guide. `rebuildInDemo` (default true) lets demo mode rebuild a missing live guide so deep links work
 * across serverless instances; the generate route passes false so a fresh request still streams the full run.
 */
export async function getGuide(slug: string, opts: { rebuildInDemo?: boolean } = {}): Promise<{ guide: Guide; tier: "library" | "live" } | null> {
  const rebuildInDemo = opts.rebuildInDemo ?? true;
  const curated = loadLibrary().find((g) => g.slug === slug);
  if (curated) return { guide: curated, tier: "library" };
  const live = await (await cache()).get(slug);
  if (live) return { guide: live, tier: "live" };
  // Demo mode: the in-memory cache does not survive a serverless cold start or a different instance, and
  // fixture guides are deterministic, so rebuild the guide silently (no fixture delays; probes still run).
  if (rebuildInDemo && process.env.MOCK_AGENT === "1" && /^[a-z0-9-]+$/.test(slug)) {
    try {
      const [{ generateGuide }, { withoutMockDelays }] = await Promise.all([import("./agent/pipeline"), import("./agent/mock")]);
      const { guide } = await withoutMockDelays(() => generateGuide(slug.replace(/-/g, " "), () => {}));
      if (guide.slug !== slug) return null;
      await saveGeneratedGuide(guide);
      return { guide, tier: "live" };
    } catch (e) {
      console.error(`Demo-mode rebuild failed for ${slug}:`, (e as Error).message);
      return null;
    }
  }
  return null;
}

export async function saveGeneratedGuide(guide: Guide): Promise<void> {
  await (await cache()).set(guide.slug, guide);
}

export async function listGeneratedGuides(): Promise<Guide[]> {
  return (await cache()).list();
}
